@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');
:root{--ink:#131719;--paper:#d4d0c4;--yellow:#d2aa4e;--red:#a8493b;--blue:#729099;--mono:'IBM Plex Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}*{box-sizing:border-box}html,body,#game-shell{margin:0;width:100%;height:100%;overflow:hidden;background:#101416;color:#e5e0d2;font-family:var(--mono);touch-action:none}#game-shell{position:relative;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.24) 77%,rgba(0,0,0,.7) 130%);z-index:1}.hidden{display:none!important}.screen{position:absolute;inset:0;z-index:9;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(8,12,13,.83),rgba(8,12,13,.48) 56%,rgba(8,12,13,.7)),radial-gradient(ellipse at 60% 50%,transparent,rgba(0,0,0,.7)}.paper-card{position:relative;width:min(470px,calc(100vw - 42px));padding:34px 42px 28px;background:#d2cec0;color:#171c1d;box-shadow:12px 14px 0 rgba(0,0,0,.25);transform:rotate(-1deg);clip-path:polygon(0 1%,99% 0,100% 98%,1% 100%)}.stamp{position:absolute;right:26px;top:24px;border:2px solid #a34a3d;color:#a34a3d;font:700 12px var(--mono);padding:5px 8px;transform:rotate(8deg);letter-spacing:1px}.eyebrow{font:600 10px var(--mono);letter-spacing:1.55px;color:#627377;margin:0 0 7px}.paper-card h1{font:900 clamp(72px,13vw,104px)/.77 var(--display);letter-spacing:-2px;margin:21px 0 22px;color:#182022}.paper-card h1 em,.paper-card h2 em{font-style:normal;color:#a44d3d}.rule{width:100%;height:1px;background:#99978d;margin:19px 0}.lede{font:500 10px/1.8 var(--mono);letter-spacing:.35px;color:#444d4c}.briefing{margin:22px 0 21px;border-left:3px solid #a44d3d;padding:7px 12px;display:grid;gap:6px}.briefing b{font:700 9px var(--mono);letter-spacing:1px;color:#8f4338}.briefing span{font:500 11px/1.65 var(--mono);color:#293132}.primary-btn{border:0;background:#a9493b;color:#f0e9d8;width:100%;padding:14px 16px;display:flex;justify-content:space-between;align-items:center;font:700 13px var(--mono);letter-spacing:1.2px;cursor:pointer;box-shadow:4px 4px 0 #77342e;transition:transform .12s,background .12s}.primary-btn:hover{background:#bd5947;transform:translateY(-2px)}.primary-btn span{font-size:20px}.start-controls{font:500 8px var(--mono);letter-spacing:.65px;text-align:center;margin-top:18px;color:#646b66}.screen-foot{position:absolute;bottom:max(18px,env(safe-area-inset-bottom));left:24px;right:24px;display:flex;justify-content:space-between;font:500 8px var(--mono);letter-spacing:1px;color:#c0bcaf;opacity:.72}.end-card{transform:rotate(.4deg)}.end-card h2{font:900 57px/.82 var(--display);letter-spacing:-1px;margin:18px 0}.loading{position:absolute;inset:0;z-index:12;display:grid;place-content:center;background:#101416;color:#d4d0c4;font:600 12px var(--mono);letter-spacing:2px}.loading span{color:#bd9d53;animation:pulse 1s infinite}@keyframes pulse{50%{opacity:.15}}
#hud{position:absolute;inset:0;z-index:3;pointer-events:none}.topbar{position:absolute;top:max(18px,env(safe-area-inset-top));left:22px;right:22px;display:flex;align-items:center;gap:26px;height:42px;text-shadow:0 2px 6px #000}.brand{display:flex;align-items:center;gap:10px;min-width:172px}.brand-mark{width:33px;height:33px;border:1px solid rgba(207,192,151,.65);display:grid;place-items:center;color:#d3ad5c;font:800 22px var(--display);transform:rotate(-4deg)}.brand div{display:grid;gap:2px}.brand b{font:800 15px var(--display);letter-spacing:1.5px}.brand small{font:500 8px var(--mono);letter-spacing:1px;color:#c0bbb0}.objective{display:flex;align-items:center;gap:8px;font:600 9px var(--mono);letter-spacing:1px;color:#dbd5c8}.live-dot{width:6px;height:6px;background:#b45041;border-radius:50%;box-shadow:0 0 8px #b45041;animation:pulse 1.4s infinite}.currency{margin-left:auto;display:grid;grid-template-columns:26px auto;grid-template-rows:17px 11px;align-items:center;column-gap:4px}.currency .coin{grid-row:1/3;color:#d3ad5c;font:700 25px var(--display)}.currency #credits{font:700 16px var(--mono);color:#eee8d8}.currency small{font:500 7px var(--mono);color:#bbb5a7;letter-spacing:1px}.wave-label{position:absolute;top:86px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;font:600 9px var(--mono);letter-spacing:1px;color:#d0cabb;white-space:nowrap;text-shadow:0 2px 6px #000}.wave-label i{width:26px;height:1px;background:#b89a56}.wave-label span:last-child{color:#aaa79c}.bottom-hud{position:absolute;left:24px;right:24px;bottom:max(20px,env(safe-area-inset-bottom));display:flex;align-items:flex-end;justify-content:space-between;gap:20px;text-shadow:0 2px 5px #000}.health-module{width:min(230px,30vw)}.stat-top{display:flex;justify-content:space-between;align-items:center;font:600 9px var(--mono);letter-spacing:1px}.stat-top b{font-size:15px;color:#ece3cf}.health-track{margin-top:7px;width:100%;height:7px;background:rgba(8,10,10,.75);border:1px solid rgba(228,222,204,.26);padding:1px}.health-track i{display:block;width:100%;height:100%;background:#a44f42;transition:width .25s}.health-note{font:500 7px var(--mono);letter-spacing:.7px;color:#c6c0b4;margin-top:6px}.weapon-module{display:flex;align-items:center;gap:11px;margin-right:auto;margin-left:clamp(15px,7vw,100px)}.weapon-icon{font:700 29px var(--display);color:#d5b45e;transform:rotate(-35deg);width:32px;text-align:center}.weapon-module div:last-child{display:grid;gap:2px}.weapon-module .eyebrow{font-size:7px;margin:0;color:#bcb7aa}.weapon-module b{font:700 13px var(--display);letter-spacing:1px}.weapon-module small{font:500 7px var(--mono);letter-spacing:.4px;color:#c6c0b4}.weapon-module small span{color:#d4b455}.controls-hint{font:500 7px var(--mono);letter-spacing:.4px;color:#c2bdae}.controls-hint span{color:#e2d7b8;border:1px solid rgba(220,210,185,.42);padding:3px 4px;margin-left:5px}.interaction{position:absolute;bottom:25%;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:8px 12px;background:rgba(15,18,18,.82);border:1px solid rgba(213,190,126,.5);font:600 9px var(--mono);letter-spacing:1px;color:#eee4ca;text-shadow:none}.keycap{border:1px solid #d5b45e;color:#d5b45e;padding:3px 6px}.toast{position:absolute;left:50%;top:25%;transform:translate(-50%,-10px);opacity:0;color:#eee5cf;background:rgba(17,21,21,.85);border-left:2px solid #d3ae5d;padding:10px 14px;font:600 9px var(--mono);letter-spacing:.8px;transition:all .22s;text-shadow:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}#crosshair{position:absolute;left:50%;top:50%;width:14px;height:14px;transform:translate(-50%,-50%);opacity:.86;transition:transform .1s}#crosshair i{position:absolute;background:#e6dfcc;width:1px;height:4px;box-shadow:0 0 3px #000}#crosshair i:nth-child(1){top:0;left:6px}#crosshair i:nth-child(2){bottom:0;left:6px}#crosshair i:nth-child(3){left:0;top:5px;width:4px;height:1px}#crosshair i:nth-child(4){right:0;top:5px;width:4px;height:1px}#crosshair b{position:absolute;width:2px;height:2px;left:6px;top:6px;background:#d8b456}#damage-flash{position:absolute;inset:0;background:rgba(162,45,33,.2);opacity:0;transition:opacity .15s}.touch-ui{display:none}.boss-title{position:absolute;top:18%;left:50%;transform:translateX(-50%);display:grid;gap:3px;text-align:center;text-shadow:0 2px 5px #000}.boss-title span{font:500 7px var(--mono);letter-spacing:2px;color:#d1b864}.boss-title b{font:800 21px var(--display);letter-spacing:1.5px}.boss-track{position:absolute;top:calc(18% + 40px);left:50%;transform:translateX(-50%);width:min(340px,64vw);height:6px;border:1px solid rgba(230,220,195,.4);background:rgba(5,8,8,.7);padding:1px}.boss-track i{display:block;width:100%;height:100%;background:#a44439;transition:width .18s}.boss-title~small{position:absolute;top:calc(18% + 54px);left:50%;transform:translateX(-50%);white-space:nowrap;font:500 7px var(--mono);letter-spacing:.8px;color:#d0c8b7;text-shadow:0 2px 5px #000}#boss-bar-wrap{display:block}#boss-bar-wrap.hidden{display:none!important}
@media(max-width:700px){.topbar{left:15px;right:15px;top:max(12px,env(safe-area-inset-top));gap:8px}.brand{min-width:0;gap:7px}.brand-mark{width:29px;height:29px;font-size:19px}.brand b{font-size:12px}.brand small{font-size:6px}.objective{font-size:7px;letter-spacing:.5px;max-width:130px}.currency #credits{font-size:14px}.currency small{font-size:6px}.wave-label{top:57px;font-size:7px}.bottom-hud{left:15px;right:15px;bottom:calc(112px + env(safe-area-inset-bottom));align-items:flex-end}.health-module{width:145px}.health-note{font-size:6px}.weapon-module{margin-left:auto;margin-right:0;gap:5px}.weapon-icon{font-size:23px;width:22px}.weapon-module .eyebrow{font-size:5px}.weapon-module b{font-size:11px}.weapon-module small{font-size:6px}.controls-hint{display:none}.touch-ui{display:block;position:absolute;inset:0;pointer-events:none}.stick-zone{position:absolute;left:16px;bottom:calc(17px + env(safe-area-inset-bottom));width:120px;height:120px;pointer-events:auto;touch-action:none}.stick-ring{position:absolute;inset:10px;border-radius:50%;border:1px solid rgba(229,219,192,.35);background:rgba(19,23,23,.19);box-shadow:inset 0 0 20px rgba(0,0,0,.16)}.stick-ring:before{content:'';position:absolute;inset:25%;border:1px dashed rgba(229,219,192,.16);border-radius:50%}.stick-ring i{position:absolute;left:50%;top:50%;width:38px;height:38px;border-radius:50%;transform:translate(-50%,-50%);background:rgba(203,182,130,.65);border:1px solid rgba(247,237,211,.55);box-shadow:0 2px 8px #000}.stick-zone>span{position:absolute;bottom:0;left:50%;transform:translateX(-50%);font:500 7px var(--mono);letter-spacing:1.2px;color:#d0c9b8}.aim-zone{left:auto;right:8px;bottom:calc(16px + env(safe-area-inset-bottom));width:145px;height:145px}.touch-action{position:absolute;pointer-events:auto;touch-action:none;border:1px solid rgba(231,219,187,.5);border-radius:50%;background:rgba(21,25,24,.75);color:#eee5ce;font:700 8px var(--mono);letter-spacing:.7px;width:53px;height:53px;box-shadow:0 2px 10px #0007}.fire-action{right:25px;bottom:calc(130px + env(safe-area-inset-bottom));width:62px;height:62px;border-color:#c25b4b;background:rgba(133,54,43,.78);font-size:9px}.kick-action{right:92px;bottom:calc(119px + env(safe-area-inset-bottom));width:48px;height:48px}.roll-action{right:105px;bottom:calc(64px + env(safe-area-inset-bottom));width:45px;height:45px;color:#d5b45e}.sprint-action{right:28px;bottom:calc(73px + env(safe-area-inset-bottom));width:42px;height:42px}.touch-action:active{transform:scale(.92);background:rgba(158,123,63,.8)}.interaction{bottom:38%;font-size:8px}.paper-card{padding:27px 26px 23px}.paper-card h1{font-size:80px}.stamp{right:18px;top:18px;font-size:9px}.briefing{margin:16px 0}.screen-foot{font-size:6px;left:12px;right:12px}.boss-title{top:15%}.boss-track{top:calc(15% + 38px)}.boss-title~small{top:calc(15% + 51px)}}
@media(min-width:701px) and (pointer:fine){#hud{cursor:none}}

import * as THREE from 'three';

const $ = (id) => document.getElementById(id);
const canvas = $('game');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x171d1f);
scene.fog = new THREE.FogExp2(0x171d1f, 0.031);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 100);
camera.rotation.order = 'YXZ';
const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.6));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.16;
renderer.shadowMap.enabled = false;

const mat = (color, roughness=1, extra={}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const M = {
  asphalt: mat(0x383c3b), concrete: mat(0x67675f), dirty: mat(0x8e876f), dark: mat(0x202728), metal: mat(0x555d5b, .8, { metalness:.35 }), rust: mat(0x704638, .85, { metalness:.2 }), yellow: mat(0xb3944b), light: mat(0xc3ac6c, .8, {emissive:0x59401b, emissiveIntensity:.3}), blue: mat(0x506671), red: mat(0x91483c), flesh: mat(0x817864), black: mat(0x252a29), glow: mat(0xd0a447,.6,{emissive:0x7d521b,emissiveIntensity:.6}), enemyGlow: mat(0xb84737,.65,{emissive:0x6d231d,emissiveIntensity:.35})
};
const hemi = new THREE.HemisphereLight(0xb4bdba, 0x34302a, 1.35); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xb5c2c1, 1.0); moon.position.set(-7, 16, -9); scene.add(moon);
const sodium = new THREE.PointLight(0xd6ac60, 35, 18, 2); sodium.position.set(-7, 5, 0); scene.add(sodium);
const redLight = new THREE.PointLight(0xa84637, 18, 11, 2); redLight.position.set(7, 3.5, -12); scene.add(redLight);

function box(parent, x,y,z, sx,sy,sz, material, rotY=0) { const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material); m.position.set(x,y,z); m.rotation.y=rotY; parent.add(m); return m; }
function cyl(parent,x,y,z,rt,rb,h,material,seg=10) { const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,seg),material); m.position.set(x,y,z); parent.add(m); return m; }
function sphere(parent,x,y,z,r,material, sx=1,sy=1,sz=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,10,8),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);parent.add(m);return m;}
function makeGroundTexture(){
  const c=document.createElement('canvas');c.width=512;c.height=512;const ctx=c.getContext('2d');ctx.fillStyle='#414442';ctx.fillRect(0,0,512,512);
  for(let i=0;i<3200;i++){const x=Math.random()*512,y=Math.random()*512,r=Math.random()*2+.3;ctx.fillStyle=Math.random()>.5?'rgba(15,18,18,.10)':'rgba(190,182,155,.07)';ctx.fillRect(x,y,r,r);}
  ctx.strokeStyle='rgba(20,23,22,.55)';ctx.lineWidth=2;for(let i=0;i<8;i++){let x=Math.random()*512,y=Math.random()*512;ctx.beginPath();ctx.moveTo(x,y);for(let n=0;n<5;n++){x+=(Math.random()-.5)*35;y+=Math.random()*27;ctx.lineTo(x,y)}ctx.stroke();}
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(4,4);t.colorSpace=THREE.SRGBColorSpace;return t;
}
const groundMat=mat(0xffffff,1);groundMat.map=makeGroundTexture();
const floor=new THREE.Mesh(new THREE.PlaneGeometry(34,34),groundMat);floor.rotation.x=-Math.PI/2;floor.position.y=-.12;scene.add(floor);
// Municipal courtyard perimeter and apartment blocks.
box(scene,0,-.05,-16,34,.5,1.2,M.concrete);box(scene,0,-.05,16,34,.5,1.2,M.concrete);box(scene,-16,-.05,0,1.2,.5,34,M.concrete);box(scene,16,-.05,0,1.2,.5,34,M.concrete);
function building(x,z,w,d,h,base,seed){
  box(scene,x,h/2,z,w,h,d,base);box(scene,x,h-.18,z,w+.15,.35,d+.14,M.dark);
  const rows=Math.floor((h-2)/2.05),cols=Math.floor((w-1)/1.8);
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
    const wx=x-w/2+1+c*(w-2)/Math.max(cols-1,1), wy=1.5+r*2.0;
    if(Math.random()<.14)continue;
    const wm=mat(Math.random()>.72?0x86794e:0x29383b,.9,{emissive:Math.random()>.83?0x392c18:0x000000,emissiveIntensity:.28});
    box(scene,wx,wy,z-d/2-.012,.78,1.12,.08,wm);
    box(scene,wx,wy-.62,z-d/2-.03,.88,.08,.14,M.dark);
  }
  // stains and narrow ledges
  for(let i=0;i<5;i++){box(scene,x-w/2+.5+i*(w-1)/4,Math.min(h-1,2.4+i%2*2.3),z-d/2-.1,.22,1.5,.04,M.dirty);}
}
building(-10,-13,11,5,12,M.concrete,1);building(10,-13,11,5,14,M.blue,2);building(-13,10,5,10,9,M.dirty,3);building(13,10,5,10,10,M.concrete,4);
// A distant block silhouette behind the arena.
box(scene,0,8,-20,38,16,3,mat(0x303738));
// Gate, signage, utility junk and damp street clutter.
box(scene,0,2.45,-15.15,5.5,.35,.4,M.rust);box(scene,-2.5,1.2,-15.1,.18,2.5,.28,M.metal);box(scene,2.5,1.2,-15.1,.18,2.5,.28,M.metal);
function signTexture(text,sub){const c=document.createElement('canvas');c.width=512;c.height=180;const x=c.getContext('2d');x.fillStyle='#303536';x.fillRect(0,0,512,180);x.fillStyle='#b9aa81';x.font='bold 54px monospace';x.fillText(text,24,76);x.fillStyle='#88877b';x.font='22px monospace';x.fillText(sub,27,125);for(let i=0;i<60;i++){x.fillStyle='rgba(0,0,0,.2)';x.fillRect(Math.random()*512,Math.random()*180,4,3)}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return new THREE.MeshBasicMaterial({map:t});}
const sign=new THREE.Mesh(new THREE.PlaneGeometry(3.2,1.1),signTexture('ДВОР № 4','УПРАВЛЯЮЩАЯ КОМПАНИЯ'));sign.position.set(0,4.2,-15.1);scene.add(sign);
for(let i=0;i<6;i++){
  const x=-12+i*4.8,z= i%2===0?8:-8;
  box(scene,x,.55,z,2.8,.65,1.15,i%2?M.blue:M.rust,Math.random()*.3);
  box(scene,x-.55,.93,z,.72,.28,1.1,M.dark);box(scene,x+.55,.93,z,.72,.28,1.1,M.dark);
  for(const wx of [x-1.05,x+1.05])for(const wz of [z-.38,z+.38])cyl(scene,wx,.27,wz,.22,.22,.12,M.black,12).rotation.z=Math.PI/2;
}
// lamps with tired pools of warm light
for(const x of [-7,7]){cyl(scene,x,2.5,-2,.09,.13,5,M.metal);box(scene,x,4.95,-2,.8,.15,.25,M.yellow);const lamp=new THREE.PointLight(0xd9ba72,19,10,2);lamp.position.set(x,4.7,-2);scene.add(lamp);}
for(let i=0;i<22;i++){
 const x=(Math.random()-.5)*27,z=(Math.random()-.5)*27;
 if(Math.abs(x)<4&&Math.abs(z)<5)continue;
 if(Math.random()>.45){const r=Math.random()*.5+.15;box(scene,x,r/2,z,r*1.6,r*.35,r,M.dirty,Math.random()*2);}
 else {cyl(scene,x,.12,z,.15,.18,.23,M.rust,7);}
}
// Pipe and the tired sleeve in the first-person view model.
const rig=new THREE.Group();camera.add(rig);scene.add(camera);
const sleeve=box(rig,.39,-.43,-.72,.24,.25,.46,M.blue,-.35);sleeve.rotation.z=-.42;
const glove=sphere(rig,.35,-.34,-.53,.14,M.flesh,.85,.7,1);
const pipe=cyl(rig,.29,-.23,-.76,.045,.055,.78,M.metal,9);pipe.rotation.z=-.28;pipe.rotation.x=.22;
const pipeEnd=cyl(rig,.39,-.05,-.96,.07,.07,.13,M.rust,9);pipeEnd.rotation.z=-.28;
const tape=box(rig,.28,-.35,-.54,.13,.06,.15,M.yellow,-.35);tape.rotation.z=-.28;

const player={pos:new THREE.Vector3(0,0,8),yaw:0,pitch:0,hp:100,maxHp:100,credits:0,kills:0,lastHurt:-99,roll:0,rollCd:0,kickCd:0,attackBuff:0,damage:16,dead:false,invuln:0};
const enemies=[], drops=[], shots=[], particles=[], chests=[];
let running=false, finished=false, wave=0, waveWait=0, boss=null, time=0, fireHeld=false, fireCd=0, shake=0, toastTimer=0, pointerLocked=false;
const moveInput={x:0,y:0,sprint:false};
const touch={moveId:null,aimId:null,moveOrigin:null,aimOrigin:null};
const raycaster=new THREE.Raycaster();raycaster.far=30;
function makeChest(x,z,cost){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,.48,0,1.05,.72,.8,M.dark);box(g,0,.86,0,1.12,.16,.87,M.yellow);box(g,0,.5,.43,.22,.18,.07,M.glow);box(g,-.47,.5,0,.08,.7,.84,M.rust);box(g,.47,.5,0,.08,.7,.84,M.rust);const light=new THREE.PointLight(0xd1a951,4,3);light.position.y=1.2;g.add(light);chests.push({group:g,x,z,cost,opened:false});}
makeChest(-5,-1,18);makeChest(5,1,18);
function makeEnemy(type,x,z){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 const data={melee:{hp:48,speed:1.55,scale:1,mat:M.flesh,value:5,range:1.45,damage:10},ranged:{hp:38,speed:1.0,scale:.95,mat:M.blue,value:7,range:8,damage:8},heavy:{hp:100,speed:.72,scale:1.48,mat:M.rust,value:11,range:1.8,damage:16}}[type];
 const torso=box(g,0,.95,0,.67,1.05,.43,data.mat);torso.rotation.z=(Math.random()-.5)*.12;
 sphere(g,0,1.68,.02,.3,type==='ranged'?M.dirty:M.flesh,.9,1,1);
 box(g,-.13,1.72,.276,.055,.035,.025,M.enemyGlow);box(g,.13,1.72,.276,.055,.035,.025,M.enemyGlow);
 for(const side of [-1,1]){box(g,side*.44,1.03,0,.19,.72,.2,data.mat,side*.1);box(g,side*.18,.32,0,.23,.7,.25,M.dark);}
 if(type==='ranged'){box(g,.43,1.12,.16,.55,.13,.14,M.metal,-.3);sphere(g,.72,1.1,.15,.11,M.yellow);}
 if(type==='heavy'){box(g,0,1.93,0,.56,.14,.53,M.metal);box(g,0,.9,.28,.42,.32,.12,M.rust);}
 const healthMat=mat(0xa9473b,{roughness:.7});const barBack=new THREE.Mesh(new THREE.BoxGeometry(1,.07,.04),M.dark);barBack.position.y=2.28;g.add(barBack);const bar=new THREE.Mesh(new THREE.BoxGeometry(.94,.045,.045),healthMat);bar.position.set(0,2.28,.04);g.add(bar);
 const e={group:g,type,hp:data.hp,maxHp:data.hp,speed:data.speed,range:data.range,damage:data.damage,value:data.value,attackCd:Math.random()+.4,stun:0,knock:new THREE.Vector3(),bar,flash:0,dead:false};g.traverse(o=>{o.userData.enemy=e});enemies.push(e);return e;
}
function spawnWave(n){wave=n;const count=[0,3,4,5][n]||3;for(let i=0;i<count;i++){const a=(i/count)*Math.PI*2+Math.random()*.35,r=9+Math.random()*2;const type=n===1?'melee':n===2?(i%3===0?'heavy':i%2?'ranged':'melee'):(i%3===0?'heavy':i%2?'ranged':'melee');makeEnemy(type,Math.cos(a)*r,-Math.sin(a)*r);}}
function beginRun(){if(running)return;running=true;$('start-screen').classList.add('hidden');$('hud').classList.remove('hidden');if(matchMedia('(pointer:coarse)').matches)$('touch-ui').style.display='block';spawnWave(1);updateHud();if(!matchMedia('(pointer:coarse)').matches)canvas.requestPointerLock?.();toast('SHIFT STARTED. PPE IS A PERSONAL CHOICE.');}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.4;}
function updateHud(){ $('credits').textContent=String(player.credits).padStart(2,'0');$('health-value').textContent=Math.ceil(player.hp);$('health-bar').style.width=`${Math.max(0,player.hp/player.maxHp*100)}%`;$('health-note').textContent=player.hp>65?'YOU LOOK TERRIBLE. STILL ALIVE.':player.hp>30?'PLEASE FILE A MEDICAL FORM.':'THIS IS BECOMING A UNION ISSUE.';$('wave-text').textContent=boss?'BOSS ENCOUNTER':`WAVE 0${wave} / 03`;$('enemy-count').textContent=boss?'1 MAJOR PROBLEM':`${enemies.length} HOSTILES`;if(boss){$('boss-bar').style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;$('boss-phase').textContent=boss.phase===1?'PHASE I · “EARLY FINISH IS NOT ON THE PLAN”':'PHASE II · MAGNETIC ACCOUNTING';}}

