function spawnBoss(){
 const g=new THREE.Group();g.position.set(0,0,-8);scene.add(g);
 // The yard foreman: pipes, conveyor plates, and a crane arm. A person-shaped labor violation.
 box(g,0,1.58,0,1.65,1.95,1.05,M.rust);box(g,0,2.77,.02,.9,.68,.78,M.metal);box(g,0,3.15,.02,1.18,.18,.94,M.yellow);
 box(g,0,1.55,.56,.52,.62,.12,M.dark);box(g,0,1.52,.64,.27,.25,.06,M.glow);
 for(const side of [-1,1]){
  box(g,side*1.03,1.73,0,.62,.55,.72,M.metal,side*.12);box(g,side*1.2,1.33,0,.48,.35,.55,M.rust);
  box(g,side*.48,.48,0,.56,.8,.58,M.dark);box(g,side*.48,.12,.12,.82,.22,1.0,M.metal);
  for(let i=0;i<3;i++)cyl(g,side*(1.12+i*.07),.45,-.08,.12,.12,.36,M.yellow,8).rotation.z=Math.PI/2;
 }
 // Crane boom and hanging magnetic hook.
 box(g,.18,3.48,0,.32,1.55,.34,M.rust,0);box(g,.7,4.2,0,1.6,.25,.3,M.metal,-.13);box(g,1.42,3.86,0,.08,.72,.1,M.dark);cyl(g,1.42,3.42,0,.1,.1,.38,M.yellow,8);box(g,1.42,3.17,0,.48,.17,.48,M.metal);
 for(let s=-1;s<=1;s+=2){box(g,s*.84,2.73,.42,.18,.12,.08,M.enemyGlow);}
 const weak=new THREE.Mesh(new THREE.OctahedronGeometry(.27,0),M.glow);weak.position.set(0,1.57,.79);g.add(weak);
 const halo=new THREE.Mesh(new THREE.TorusGeometry(1.35,.04,5,24),new THREE.MeshBasicMaterial({color:0xb34b3c,transparent:true,opacity:.65}));halo.rotation.x=Math.PI/2;halo.position.y=.025;g.add(halo);
 boss={group:g,hp:245,maxHp:245,phase:1,attackCd:2.1,state:'idle',stateTime:0,attackTarget:new THREE.Vector3(),weak,halo,flash:0};$('boss-bar-wrap').classList.remove('hidden');$('objective-text').textContent='PUT THE FOREMAN OUT OF OFFICE';toast('SUPERVISOR ON SITE. TRY TO LOOK BUSY.');updateHud();
}
function spawnDrop(pos,value){const g=new THREE.Group();g.position.copy(pos);g.position.y=.38;scene.add(g);const coin=new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,.07,12),M.glow);coin.rotation.x=Math.PI/2;g.add(coin);const ring=new THREE.Mesh(new THREE.TorusGeometry(.23,.025,5,14),new THREE.MeshBasicMaterial({color:0xd9b552}));ring.rotation.x=Math.PI/2;g.add(ring);drops.push({group:g,value,phase:Math.random()*6});}
function burst(pos,color,count=8){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.BoxGeometry(.07,.07,.07),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));mesh.position.copy(pos);scene.add(mesh);particles.push({mesh,vel:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3),life:.42+Math.random()*.35});}}
function enemyDeath(e){if(e.dead)return;e.dead=true;scene.remove(e.group);player.kills++;player.hp=Math.min(player.maxHp,player.hp+2);spawnDrop(e.group.position,e.value);burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),e.type==='heavy'?0xa95a3c:0x9b9477,10);updateHud();}
function hurtPlayer(amount){if(player.invuln>0||player.dead||!running)return;player.hp=Math.max(0,player.hp-amount);player.lastHurt=time;player.invuln=.24;shake=.16;$('damage-flash').style.opacity='.8';setTimeout(()=>$('damage-flash').style.opacity='0',100);updateHud();if(player.hp<=0)endRun(false);}
function hitEnemy(e,damage,fromKick=false){if(e.dead)return;e.hp-=damage;e.flash=.12;e.group.traverse(o=>{if(o.material&&o.material.emissive)o.material.emissive.setHex(0x5c2119)});e.bar.scale.x=Math.max(.01,e.hp/e.maxHp);e.bar.position.x=-(1-e.hp/e.maxHp)*.46;burst(e.group.position.clone().add(new THREE.Vector3(0,1,0)),fromKick?0xc7ad69:0xa94e3d,fromKick?5:3);if(e.hp<=0)enemyDeath(e);}
function hitBoss(damage){if(!boss||boss.hp<=0)return;const weakOpen=boss.state==='recover'||boss.phase===2;const dealt=damage*(weakOpen?2:1);boss.hp-=dealt;boss.flash=.1;burst(boss.group.position.clone().add(new THREE.Vector3(0,1.6,.7)),weakOpen?0xe4c252:0x9d4c3b,weakOpen?8:4);if(boss.hp<=boss.maxHp*.5&&boss.phase===1){boss.phase=2;boss.state='idle';boss.attackCd=.6;toast('MAGNETIC LIFT ENGAGED. SECURE YOUR LOOSE CHANGE.');}if(boss.hp<=0){boss.hp=0;updateHud();bossDeath();}else updateHud();}
function shoot(){if(!running||player.dead||fireCd>0)return;fireCd=.24;rig.position.z=.06;setTimeout(()=>rig.position.z=0,65);raycaster.setFromCamera(new THREE.Vector2(0,0),camera);let best=null,bestDist=Infinity;
 const direction=new THREE.Vector3();camera.getWorldDirection(direction);
 for(const e of enemies){if(e.dead)continue;const target=e.group.position.clone().add(new THREE.Vector3(0,1.12,0));const to=target.clone().sub(camera.position);const dist=to.length();const dot=direction.dot(to.normalize());const tolerance=Math.max(.035,.18/dist);if(dot>1-tolerance&&dist<bestDist){best=e;bestDist=dist;}}
 if(best)hitEnemy(best,player.damage*(player.attackBuff>0?1.5:1));else if(boss){const target=boss.group.position.clone().add(new THREE.Vector3(0,1.6,0));const to=target.clone().sub(camera.position);const dist=to.length();const dot=direction.dot(to.normalize());if(dot>1-Math.max(.045,.22/dist))hitBoss(player.damage*(player.attackBuff>0?1.5:1));}
 // Pipe spits sparks and has a crisp improvised-metal report.
 const flash=new THREE.PointLight(0xffc475,4,2);flash.position.set(.28,-.2,-1);camera.add(flash);setTimeout(()=>camera.remove(flash),45);
}
function kick(){if(!running||player.kickCd>0)return;player.kickCd=.85;const dir=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));let count=0;for(const e of enemies){const delta=e.group.position.clone().sub(player.pos);const dist=delta.length();if(dist<2.45&&dir.dot(delta.normalize())>.22){hitEnemy(e,13,true);e.stun=1.15;e.knock.copy(dir).multiplyScalar(5);count++;}}if(boss){const delta=boss.group.position.clone().sub(player.pos);if(delta.length()<2.8&&dir.dot(delta.normalize())>.1){hitBoss(10);boss.state='recover';boss.stateTime=1.1;count++;}}rig.rotation.x=-.14;setTimeout(()=>rig.rotation.x=0,120);if(count)toast('KICK: MANAGEMENT HAS BEEN NOTIFIED.');}
function roll(){if(!running||player.rollCd>0)return;player.roll=.48;player.rollCd=1.25;player.invuln=.5;const dir=new THREE.Vector3(moveInput.x,0,moveInput.y);if(dir.length()<.1)dir.set(0,0,-1);dir.applyAxisAngle(new THREE.Vector3(0,1,0),player.yaw).normalize();player.rollDir=dir;}
function unlockMovement(pos){const v=pos.clone();v.x=THREE.MathUtils.clamp(v.x,-14.5,14.5);v.z=THREE.MathUtils.clamp(v.z,-14.5,14.5);return v;}
function chestCheck(){let nearest=null,dist=2.7;for(const c of chests){if(c.opened)continue;const d=Math.hypot(player.pos.x-c.x,player.pos.z-c.z);if(d<dist){dist=d;nearest=c;}}if(nearest){$('interaction').classList.remove('hidden');$('interaction-text').textContent=`OPEN CRATE · ${nearest.cost} CREDITS`;return nearest;}$('interaction').classList.add('hidden');return null;}
function openChest(){const c=chestCheck();if(!c)return;if(player.credits<c.cost){toast('NOT ENOUGH CREDITS. FILE A REQUISITION.');return;}player.credits-=c.cost;c.opened=true;c.group.rotation.z=-.42;c.group.children.forEach(o=>{if(o.material===M.yellow)o.material=M.glow});player.hp=Math.min(player.maxHp,player.hp+28);player.attackBuff=18;toast('CRATE OPENED: HOT TEA, CLEAN BANDAGE, QUESTIONABLE BOLTS.');updateHud();}
function bossDeath(){if(!boss)return;scene.remove(boss.group);const leftover=player.credits;const hpGain=Math.min(25,Math.floor(leftover/2));player.maxHp+=hpGain;player.hp=Math.min(player.maxHp,player.hp+hpGain);player.credits=0;spawnDrop(new THREE.Vector3(0,.3,-8),35);toast(`FOREMAN CLOCKED OUT. +${hpGain} MAX VITALS FROM UNUSED CREDITS.`);setTimeout(()=>endRun(true),1900);}
function endRun(won){if(finished)return;finished=true;running=false;document.exitPointerLock?.();$('hud').classList.add('hidden');$('end-screen').classList.remove('hidden');$('end-kicker').textContent=won?'SHIFT COMPLETE':'CONTRACT TERMINATED';$('end-title').innerHTML=won?'THE YARD IS<br/><em>QUIET.</em>':'YOU HAVE<br/><em>FALLEN OVER.</em>';$('end-copy').textContent=won?'The Foreman has been reassigned to the afterlife. Your shift bonus is pending.' :'The pipe remains in municipal custody. Your benefits do not.';$('end-stats').innerHTML=`${player.kills} hostile${player.kills===1?'':'s'} removed<br/>${won?'+1 COMPONENTS · BOSS BOUNTY':'IN-RUN CREDITS LOST'}<br/>${player.maxHp} maximum vitality`;}
function restart(){location.reload();}

function enemyProjectile(origin,target,damage,speed=6){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.12,8,6),new THREE.MeshBasicMaterial({color:0xb34b3c}));mesh.position.copy(origin);scene.add(mesh);const velocity=target.clone().sub(origin).normalize().multiplyScalar(speed);shots.push({mesh,velocity,damage,life:5});}
function updateEnemies(dt){
 for(const e of [...enemies]){
  if(e.dead)continue;e.attackCd-=dt;e.stun=Math.max(0,e.stun-dt);e.flash=Math.max(0,e.flash-dt);
  if(e.stun<=0){const delta=player.pos.clone().sub(e.group.position);delta.y=0;const dist=delta.length();const dir=delta.clone().normalize();e.group.rotation.y=Math.atan2(dir.x,dir.z);
   if(e.type==='ranged'){
    if(dist>e.range+1)e.group.position.addScaledVector(dir,e.speed*dt);else if(dist<e.range-2)e.group.position.addScaledVector(dir,-e.speed*.65*dt);
    if(e.attackCd<=0&&dist<12){e.attackCd=2.1;enemyProjectile(e.group.position.clone().add(new THREE.Vector3(0,1.3,0)),camera.position.clone().add(new THREE.Vector3(0,-.25,0)),e.damage,6.7);}
   }else if(dist>e.range){e.group.position.addScaledVector(dir,e.speed*dt);}
   else if(e.attackCd<=0){e.attackCd=e.type==='heavy'?1.65:1.35; if(dist<e.range+.35)hurtPlayer(e.damage);}
  }
  if(e.knock.lengthSq()>.01){e.group.position.addScaledVector(e.knock,dt);e.knock.multiplyScalar(Math.max(0,1-dt*4));}
  e.group.position.x=THREE.MathUtils.clamp(e.group.position.x,-14.5,14.5);e.group.position.z=THREE.MathUtils.clamp(e.group.position.z,-14.5,14.5);
 }
 for(let i=enemies.length-1;i>=0;i--)if(enemies[i].dead)enemies.splice(i,1);
}
function damageBossAttack(){const distance=Math.hypot(boss.group.position.x-player.pos.x,boss.group.position.z-player.pos.z);if(distance<3.1){hurtPlayer(boss.phase===2?23:17);const away=player.pos.clone().sub(boss.group.position).setY(0).normalize();player.pos.addScaledVector(away,1.1);}}
function updateBoss(dt){if(!boss||boss.hp<=0)return;const b=boss;b.attackCd-=dt;b.group.rotation.y=Math.atan2(player.pos.x-b.group.position.x,player.pos.z-b.group.position.z);const delta=player.pos.clone().sub(b.group.position);delta.y=0;const dist=delta.length();
 if(b.state==='idle'){
   if(dist>3.2)b.group.position.addScaledVector(delta.normalize(),(b.phase===2?1.12:.72)*dt);
   if(b.attackCd<=0){b.state='windup';b.stateTime=1.05;b.attackTarget.copy(player.pos);b.attackCd=b.phase===2?2.45:3.1;toast(b.phase===2?'MAGNETIC CRANE WINDING UP — MOVE!':'THE FOREMAN IS PREPARING A SAFETY INCIDENT.');}
 }else if(b.state==='windup'){
  b.stateTime-=dt;b.weak.material=M.glow;b.weak.scale.setScalar(1.35+Math.sin(time*18)*.18);b.halo.material.opacity=.85;
  if(b.stateTime<=0){b.state=b.phase===2?'charge':'slam';b.stateTime=b.phase===2?.62:.5;}
 }else if(b.state==='charge'){
  const chargeDir=player.pos.clone().sub(b.group.position).setY(0).normalize();b.group.position.addScaledVector(chargeDir,5.6*dt);b.halo.material.opacity=.3;b.stateTime-=dt;if(Math.hypot(b.group.position.x-player.pos.x,b.group.position.z-player.pos.z)<2.5)damageBossAttack();if(b.stateTime<=0){b.state='recover';b.stateTime=1.35;}
 }else if(b.state==='slam'){
  b.stateTime-=dt;if(b.stateTime<=0){damageBossAttack();b.state='recover';b.stateTime=1.1;burst(b.group.position.clone().add(new THREE.Vector3(0,.1,0)),0xc3a453,16);}
 }else if(b.state==='recover'){b.stateTime-=dt;b.weak.material=M.glow;b.weak.scale.setScalar(1.5);b.halo.material.opacity=.45;if(b.stateTime<=0){b.state='idle';b.weak.scale.setScalar(1);b.halo.material.opacity=.65;}}
 b.group.position.x=THREE.MathUtils.clamp(b.group.position.x,-12,12);b.group.position.z=THREE.MathUtils.clamp(b.group.position.z,-12,12);
}
function updateDrops(dt){for(let i=drops.length-1;i>=0;i--){const d=drops[i];d.phase+=dt*2;d.group.rotation.y+=dt*1.5;d.group.position.y=.38+Math.sin(d.phase)*.12;const dist=Math.hypot(d.group.position.x-player.pos.x,d.group.position.z-player.pos.z);if(dist<1.35){player.credits+=d.value;toast(`+${d.value} CREDITS · CITY EMPLOYEE OF THE MONTH`);scene.remove(d.group);drops.splice(i,1);updateHud();}}}
function updateShots(dt){for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.mesh.position.addScaledVector(s.velocity,dt);s.life-=dt;if(s.life<=0||s.mesh.position.distanceTo(camera.position)>22){scene.remove(s.mesh);shots.splice(i,1);continue;}if(s.mesh.position.distanceTo(camera.position)<.6){hurtPlayer(s.damage);scene.remove(s.mesh);shots.splice(i,1);}}}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);p.vel.y-=5*dt;p.mesh.material.opacity=Math.max(0,p.life);p.mesh.rotation.x+=dt*4;if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1);}}}
function updatePlayer(dt){
 player.rollCd=Math.max(0,player.rollCd-dt);player.kickCd=Math.max(0,player.kickCd-dt);player.invuln=Math.max(0,player.invuln-dt);player.attackBuff=Math.max(0,player.attackBuff-dt);fireCd=Math.max(0,fireCd-dt);
 if(fireHeld)shoot();
 let desired=new THREE.Vector3(moveInput.x,0,-moveInput.y);if(desired.length()>1)desired.normalize();desired.applyAxisAngle(new THREE.Vector3(0,1,0),player.yaw);
 if(player.roll>0){player.roll-=dt;desired.copy(player.rollDir);}
 const speed=player.roll>0?10:moveInput.sprint?7.4:4.7;player.pos.addScaledVector(desired,speed*dt);
 player.pos.x=THREE.MathUtils.clamp(player.pos.x,-14.6,14.6);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-14.6,14.6);
 // crude collision response against the parked cars
 for(let i=0;i<6;i++){const x=-12+i*4.8,z=i%2===0?8:-8;const dx=player.pos.x-x,dz=player.pos.z-z;if(Math.abs(dx)<1.9&&Math.abs(dz)<1.05){if(Math.abs(dx)>Math.abs(dz))player.pos.x=x+Math.sign(dx)*1.9;else player.pos.z=z+Math.sign(dz)*1.05;}}
 camera.position.set(player.pos.x,1.65+(player.roll>0?-.35*Math.sin((.48-player.roll)/.48*Math.PI):0),player.pos.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');camera.fov=THREE.MathUtils.lerp(camera.fov,moveInput.sprint?79:73,Math.min(1,dt*5));camera.updateProjectionMatrix();
 rig.position.y=-.03+Math.sin(time*10)*(desired.length()>.05?.012:0);rig.rotation.z=desired.length()>.05?Math.sin(time*9)*.025:0;
 if(time-player.lastHurt>4&&player.hp<player.maxHp){player.hp=Math.min(player.maxHp,player.hp+5*dt);updateHud();}
}
function updateWaves(dt){if(enemies.length===0&&!boss){waveWait+=dt;if(wave<3){$('objective-text').textContent='COURTYARD TEMPORARILY UNDERSTAFFED';if(waveWait>2.2){waveWait=0;spawnWave(wave+1);$('objective-text').textContent='CLEAR THE COURTYARD';toast('MORE MUNICIPAL SERVICES HAVE ARRIVED.');updateHud();}}else if(waveWait>2.5){waveWait=0;spawnBoss();}}}
function updateInteraction(){const chest=chestCheck();if(chest){} }
