content.text:
.loading{position:absolute;inset:0;z-index:12;display:grid;place-content:center;background:#101416;color:#d4d0c4;font:600 12px var(--mono);letter-spacing:2px}
.loading span{color:#bd9d53;animation:pulse 1s infinite}
.toast{position:absolute;left:50%;top:25%;transform:translate(-50%,-10px);opacity:0;color:#eee5cf;background:rgba(17,21,21,.85);border-left:2px solid #d3ae5d;padding:10px 14px;font:600 9px var(--mono);letter-spacing:.8px;transition:all .22s;text-shadow:none;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
#damage-flash{position:absolute;inset:0;background:rgba(162,45,33,.2);opacity:0;transition:opacity .15s}
.touch-ui{display:none}
.touch-ui{display:block;position:absolute;inset:0;pointer-events:none}

